// README block (FR-408, FR-412): rendered ONLY from the latest LIVE report (evals/reports/
// latest.json). `pnpm evals:readme` regenerates it; `pnpm evals:readme --check` (CI) fails when
// the README's block differs from a fresh render — the numbers cannot be edited by hand.

import { existsSync, readFileSync } from "node:fs";
import { HONESTY_LINE, type RunReport } from "./report";

export const START_MARKER = "<!-- evals:start -->";
export const END_MARKER = "<!-- evals:end -->";
const GENERATED_NOTE =
  "_Generated by `pnpm evals:readme` from `evals/reports/latest.json` — do not edit by hand; CI runs `pnpm evals:readme --check`._";

const pct = (v: number | null): string => (v === null ? "n/a" : `${(v * 100).toFixed(1)} %`);
const secs = (v: number | null): string => (v === null ? "n/a" : `${(v / 1000).toFixed(1)} s`);
const usd = (v: number | null): string => (v === null ? "n/a" : `US$ ${v.toFixed(4)}`);

export function readLatestLiveReport(path: string): RunReport | null {
  if (!existsSync(path)) return null;
  const report = JSON.parse(readFileSync(path, "utf8")) as RunReport;
  if (report.mode !== "live")
    throw new Error(`${path}: expected a live report, got mode "${report.mode}"`);
  return report;
}

export function renderBlock(report: RunReport | null): string {
  const lines: string[] = [START_MARKER, GENERATED_NOTE, ""];
  if (report === null) {
    lines.push(
      "**No live evaluation published yet.** The deterministic gate (golden set through the real orchestrator with the scripted stand-in) runs on every change — see the `evals` workflow. The first live run against the production model publishes its numbers here through a pull request.",
    );
  } else {
    const m = report.metrics;
    const day = report.date.slice(0, 10);
    lines.push(
      `**Latest live evaluation** — ${day} · model \`${report.model ?? "—"}\` · prompt \`${report.promptVersion}\` · commit \`${report.commit}\` · ${report.summary.cases} cases × ${report.repetitions} executions per case${report.partial ? " · ⚠️ **partial run** (stopped by the spend cap)" : ""}`,
    );
    lines.push("");
    lines.push("| Metric | Value |");
    lines.push("|---|---|");
    lines.push(`| Task success (overall) | ${pct(m.taskSuccess.overall)} |`);
    for (const [cat, v] of Object.entries(m.taskSuccess.byCategory))
      lines.push(`| Task success — ${cat} | ${pct(v)} |`);
    lines.push(`| Tool-call accuracy | ${pct(m.toolCallAccuracy)} |`);
    lines.push(
      `| Injection resistance (adversarial cases with zero unauthorized writes) | ${pct(m.injectionResistance)} |`,
    );
    lines.push(
      `| Escalation precision / recall — deterministic triage alone | ${pct(m.escalation.triage.precision)} / ${pct(m.escalation.triage.recall)} |`,
    );
    lines.push(
      `| Escalation precision / recall — full agent | ${pct(m.escalation.agent.precision)} / ${pct(m.escalation.agent.recall)} |`,
    );
    lines.push(
      `| Latency per conversation p50 / p95 | ${secs(m.latency.conversationP50Ms)} / ${secs(m.latency.conversationP95Ms)} |`,
    );
    lines.push(
      `| Latency per turn p50 / p95 | ${secs(m.latency.turnP50Ms)} / ${secs(m.latency.turnP95Ms)} |`,
    );
    lines.push(`| Estimated cost per conversation | ${usd(m.cost.perConversationUsd)} |`);
    lines.push(`| Errors (timeouts, rate limits, invalid outputs) | ${m.errors.total} |`);
    lines.push(
      `| Judge (tone / clarity, never a gate) | ${report.judge.enabled ? `${report.judge.model} · rubric ${report.judge.rubricVersion}` : "not run"} |`,
    );
  }
  lines.push("");
  lines.push(`> ${HONESTY_LINE}`);
  lines.push(END_MARKER);
  return lines.join("\n");
}

function locate(readme: string): { start: number; end: number } {
  const starts = [...readme.matchAll(new RegExp(START_MARKER, "g"))].map((m) => m.index);
  const ends = [...readme.matchAll(new RegExp(END_MARKER, "g"))].map((m) => m.index);
  if (starts.length !== 1 || ends.length !== 1 || ends[0] < starts[0]) {
    throw new Error(`README must contain exactly one ${START_MARKER} … ${END_MARKER} marker pair`);
  }
  return { start: starts[0], end: ends[0] + END_MARKER.length };
}

export function applyBlock(readme: string, block: string): string {
  const { start, end } = locate(readme);
  return readme.slice(0, start) + block + readme.slice(end);
}

export function checkBlock(
  readme: string,
  block: string,
): { ok: true } | { ok: false; reason: string } {
  let range: { start: number; end: number };
  try {
    range = locate(readme);
  } catch (e) {
    return { ok: false, reason: (e as Error).message };
  }
  const current = readme.slice(range.start, range.end);
  if (current === block) return { ok: true };
  return {
    ok: false,
    reason:
      "README evaluation block differs from the latest report — regenerate it with `pnpm evals:readme` (numbers are never hand-written)",
  };
}
